import heapq

dist = {start: 0}
pq = [(0, start)]

while pq:
    d, u = heapq.heappop(pq)

    if d != dist[u]:
        continue

    for v, w in neighbors(u):
        nd = d + w

        if nd &lt; dist.get(v, float("inf")):
            dist[v] = nd
            heapq.heappush(pq, (nd, v))


