Union-Find
class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])

        return self.parent[x]

    def union(self, a, b):
        a = self.find(a)
        b = self.find(b)

        if a == b:
            return False

        if self.size[a] &lt; self.size[b]:
            a, b = b, a

        self.parent[b] = a
        self.size[a] += self.size[b]

        return True

45. Final mental model
Do not start with:
Is this a DP problem?
Is this a graph problem?
Start with:
\[
\boxed{
\text{state}
\rightarrow
\text{transition}
\rightarrow
\text{objective}
\rightarrow
\text{processing order}
}
\]
Then:
\[
\boxed{
\text{DP and graph algorithms are different execution strategies over state-transition systems.}
}
\]
The recurring questions are:

What information defines an equivalent future?
What are the legal transitions?
What quantity is being propagated?
When is a state’s value safe to use or finalize?

If you can answer those four questions, most interview DP and graph problems stop being collections of tricks and become instances of the same underlying framework.

Minimal PyTorch Implementations

import math
import torch


def sigmoid(x):
    # PyTorch's primitive is numerically safer than naively computing exp(-x).
    return torch.sigmoid(x)


def relu(x):
    return torch.maximum(x, torch.zeros_like(x))


def gelu_exact(x):
    return 0.5 * x * (1.0 + torch.erf(x / math.sqrt(2.0)))


def silu(x):
    return x * torch.sigmoid(x)


x = torch.linspace(-5, 5, 101, requires_grad=True)
torch.testing.assert_close(gelu_exact(x), torch.nn.functional.gelu(x))
torch.testing.assert_close(silu(x), torch.nn.functional.silu(x))


Inspect the gradients

inputs = torch.tensor([-10.0, -1.0, 0.0, 1.0, 10.0], requires_grad=True)


def values_and_gradients(fn, inputs):
    values = fn(inputs)
    gradients = torch.autograd.grad(values.sum(), inputs, retain_graph=True)[0]
    return values.detach(), gradients


for name, fn in {
    "sigmoid": sigmoid,
    "relu": relu,
    "gelu": gelu_exact,
    "silu": silu,
}.items():
    values, gradients = values_and_gradients(fn, inputs)
    print(name, "values:", values, "gradients:", gradients)

